"""Seal original failed, cancelled and superseded evidence without filling gaps."""
from pathlib import Path
import hashlib,json,re,zipfile
b=Path('/workspace/2237-cache-duplication');root=Path('/workspace/dtos-publisher-2237');m=json.loads((b/'source.json').read_text());files={}
for folder in ['canonical-first-compile-permission','canonical-second-setup-incomplete','canonical-superseded-b743-cancelled','host-failed-4fb-attempt1']:
 for p in (b/folder).rglob('*'):
  if p.is_file():files['prior/'+folder+'/'+str(p.relative_to(b/folder))]=p.read_bytes()
names=['canonical-4fb-attempt1-failed-original.zip','host-timeout-attempt1-original-api.json','host-failed-4fb-attempt1-result.json','host-timeout-diagnosis.json','host-timeout-diagnosis.log','host-timeout-prior-run-comparison.json','diagnose-host-timeout.py','focused-first.log','focused-corrected.log','focused-exact-first.log','b743-focused-exact.log','focused-reconciled-wip.log','lint-first.log','lint-corrected.log','canonical-first-compile-permission-console.log','canonical-second-setup-incomplete-console.log','canonical-superseded-b743-cancelled-console.log','compile-permission-reconciliation.json','prior-b743-local-cancellation.json','prior-b743-hosted-records-before-source-update.json','prior-b743-hosted-records-final.json','prior-b743-host-canonical-cancel.log','prior-b743-preflight-original.zip','prior-b743-canonical-cancelled-original.zip','prior-b743-canonical-cancelled-verification.json','candidate-b743.patch','source-b743.json','source-reconciliation.json','cache-memory-verification-first-missing-policy-args.log','verify-memory-first-missing-policy-args.py']
for name in names:
 p=b/name
 if p.is_file():files['prior/'+name]=p.read_bytes()
files['README.md']=b'''# Prior evidence only\n\nThese are original failed, interrupted or superseded controls, never final acceptance. A test-index assertion and nonexistent test names were corrected without weakening application checks. Read-only Ruff cache and root-owned generated bytecode were environment/setup failures; original artifacts were moved outside the source without permission changes or elevated testing. A setup inventory could not hash existing inaccessible generated pycs; their metadata and locally preserved original location are recorded. The superseded local b743 run stopped after356completed tests/357started and six passed gates. Hosted public-browser assertions passed but the preflight sentinel referenced the old decoder alias; two entry tests used the same obsolete spy. They now watch the shared loader with all no-decode assertions retained. The original canceled hosted ZIP lacks final result/manifest; it is incomplete and those files are not reconstructed. A later metadata postprocessor expected that missing result; the byte-verified artifact and limitation are kept. The memory comparison postprocessor initially omitted explicit policy arguments; captured measurements were unaffected and the corrected reader passed. Successful exploratory consoles are retained separately; some early successful structured summaries were superseded before sealing and are not final proof. The first4fb hosted canonical attempt hit the4200s overall validator deadline after4008completed tests with no recorded test failures/errors/skips and no OOM. Its full regression and last gates are incomplete. Original ZIP SHA e8e6d8b537ad02ca358aada1451778b663e500abe8dc524b887262150c83dbb8 and attempt1 API records remain here. One bounded fresh-runner retry reuses the exact source and unchanged controls. Broad per-test slowdown is measured; hardware cause is not established. Final exact-source acceptance belongs in the recovery archive only if that retry passes, not this file.\n'''
pattern=re.compile(rb'(gh[pousr]_[A-Za-z0-9]{30,}|github_pat_[A-Za-z0-9_]{60,}|-----BEGIN (?:RSA |EC |OPENSSH )?PRIVATE KEY-----)')
for n,data in files.items():assert not pattern.search(data),n
rows=[dict(name=n,bytes=len(data),sha256=hashlib.sha256(data).hexdigest()) for n,data in sorted(files.items())]
files['prior-manifest.json']=json.dumps(dict(candidate=m['candidate'],tree=m['tree'],scope='prior-attempts-only',files=rows),indent=2).encode()+b'\n'
p=root/'.github/release-plans/2237-prior.zip';assert not p.exists()
with zipfile.ZipFile(p,'w',zipfile.ZIP_DEFLATED,compresslevel=6) as z:
 for n,data in sorted(files.items()):z.writestr(n,data)
with zipfile.ZipFile(p) as z:assert z.testzip() is None
assert p.stat().st_size<100*1024**2
(b/'package-prior-report.json').write_text(json.dumps(dict(bytes=p.stat().st_size,sha256=hashlib.file_digest(p.open('rb'),'sha256').hexdigest(),entries=len(rows)),indent=2)+'\n');print('Original prior payloads sealed:',len(rows))
